 private:
  static bool sameName(const char* a, const char* b) {
    for (; *a && *b; ++a, ++b) {
      uint8_t x = static_cast<uint8_t>(*a);
      uint8_t y = static_cast<uint8_t>(*b);
      if (x >= 'A' && x <= 'Z') x += 'a' - 'A';
      if (y >= 'A' && y <= 'Z') y += 'a' - 'A';
      if (x != y) return false;
    }
    return !*a && !*b;
  }
